                (*out).size = ((*out).size as c_ulong).wrapping_add(length as c_ulong) as size_t;

                let out_data = (*out).data;
                if (distance as size_t) < length {
                    let dist = distance as size_t;
                    lodepng_memcpy(
                        out_data.wrapping_add(start) as *mut c_void,
                        out_data.wrapping_add(backward) as *const c_void,
